INSERT INTO zt_tenet (code, label, definition) VALUES ('EverythingIsAResource', 'Everything is a resource', 'Every data source and computing service is a resource, whatever its size, including the devices an organization lets reach its resources.');
INSERT INTO zt_tenet (code, label, definition) VALUES ('CommunicationIsSecuredAnywhere', 'Communication is secured anywhere', 'Every communication is protected for confidentiality, integrity and the authentication of its source, and a network location alone grants no trust.');
INSERT INTO zt_tenet (code, label, definition) VALUES ('AccessIsPerSession', 'Access is per session', 'Access to one resource is granted for one session with the least privilege the task needs, after the requester is evaluated; a grant for one resource carries to no other.');
INSERT INTO zt_tenet (code, label, definition) VALUES ('PolicyIsDynamic', 'Policy is dynamic', 'Access is decided by rules over the observable state of the identity, the application and the requesting asset, and over behavior and the environment, stricter as the resource is more sensitive.');
INSERT INTO zt_tenet (code, label, definition) VALUES ('PostureIsMonitored', 'Posture is monitored', 'The organization measures the integrity and security posture of every asset it owns or is associated with, and trusts no asset for what it is.');
INSERT INTO zt_tenet (code, label, definition) VALUES ('EnforcementIsDynamic', 'Authentication and authorization are dynamic and enforced', 'Authentication and authorization are repeated on the events the policy names and strictly enforced before access, as a constant cycle of access, assessment and adaptation.');
INSERT INTO zt_tenet (code, label, definition) VALUES ('StateIsCollected', 'State is collected', 'The organization collects as much as it can about the state of its assets, network and communications and uses it to improve the policy and its enforcement.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('Identity', 'Identity', 'Who or what asks for access: enterprise-managed identities, strong authentication that resists phishing, and the identity systems that hold them.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('Devices', 'Devices', 'What the request comes from: the inventory of every device in use, its state, and the ability to prevent, detect and respond to incidents on it.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('Networks', 'Networks', 'How the request travels: encrypted traffic and names, and perimeters broken into isolated environments.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('ApplicationsAndWorkloads', 'Applications and workloads', 'What the request reaches: applications treated as reachable from the internet, tested rigorously and open to outside reports of weaknesses.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('Data', 'Data', 'What is protected: data that is categorized, protected by what its category needs, and whose access is monitored and logged.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('VisibilityAndAnalytics', 'Visibility and analytics', 'A theme across the areas: the collection and analysis of what happens, which feeds the decisions.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('AutomationAndOrchestration', 'Automation and orchestration', 'A theme across the areas: the decisions and responses that machines carry out by policy.');
INSERT INTO zt_pillar (code, label, definition) VALUES ('Governance', 'Governance', 'A theme across the areas: the policies, roles and accountability that decide how the areas are run.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('Diagnostics', 'Continuous diagnostics and mitigation', 'The system that gathers the current state of assets and applies updates to their configuration and software, and so tells the engine what a requesting asset runs and whether it is vulnerable.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('ComplianceSystem', 'Compliance system', 'The system that holds the rules of the regime the organization falls under, so that the policy follows them.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('ThreatIntelligence', 'Threat intelligence', 'Feeds, internal or external, about newly found attacks, weaknesses and malware that the engine weighs.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('ActivityLogs', 'Network and system activity logs', 'The aggregate of asset logs, traffic and access actions that gives near real time feedback on posture.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('AccessPolicies', 'Data access policies', 'The attributes, rules and policies about access to resources, the starting point for authorizing it.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('PublicKeyInfrastructure', 'Public key infrastructure', 'The system that issues and logs the certificates of resources, subjects, services and applications.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('IdentityManagement', 'Identity management', 'The system that creates, stores and manages the accounts and identity records, with the role and attributes of each.');
INSERT INTO zt_data_source (code, label, definition) VALUES ('EventManagement', 'Security information and event management', 'The system that collects security information for analysis, to refine policy and warn of attacks.');
